/* Design fixtures only. No network, shell, session or deployment operations. */
'use strict';
const concept=document.body.dataset.concept;
const params=new URLSearchParams(location.search);
const frame=['overview','connected','changed','phone'].includes(params.get('frame'))?params.get('frame'):'overview';
const initialChanged=frame==='changed';
const state={view:frame,tab:initialChanged?'Updates':frame==='phone'?'Result':'Inputs',selected:'Implement',phase:initialChanged?'changed':'running',paused:false,split:frame==='connected'||initialChanged,inspector:true,mode:'Scroll',version:initialChanged?2:1,consumed:1,reruns:0,queued:initialChanged,delivery:initialChanged?'queued':'consumed',attached:false,retryFailed:false,pending:false,revision:1,definition:'Improve catalog search',draft:'',search:'',group:'Active work',theme:params.get('theme')||'light',notes:[],released:false,attention:true,target:'demo-preview',allowRelease:true};
const names=['Research','Implement','Review','Deploy'];
const app=document.getElementById('app'),dialog=document.getElementById('dialog');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pill=(text,type='')=>`<span class="pill ${type}">${type==='live'?'<i class="dot"></i>':''}${text}</span>`;
const button=(action,label,cls='')=>`<button type="button" data-action="${action}" class="${cls}">${label}</button>`;
let toastTimer;
function toast(text){const t=document.getElementById('toast');t.textContent=text;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',6000)}
function syncDraft(){const draft=document.getElementById('draft');if(draft)state.draft=draft.value}
function statusFor(name){if(name==='Deploy'&&!state.allowRelease)return 'Not included';if(state.phase==='stopped')return name==='Research'?'Finished':'Cancelled';if(name==='Research')return 'Finished';if(state.phase==='complete')return name==='Deploy'?'Ready to deploy':'Finished';if(name==='Implement')return state.phase==='proposal'?'Proposed':state.reruns?'Agent running · #2':'Agent running';if(name==='Review')return state.queued?'Review outdated':state.phase==='proposal'?'Proposed':'Waiting for input';return state.queued?'Release blocked':'Waiting for review'}
function steps(){return names.map((name,i)=>`<button type="button" class="step ${state.selected===name?'active':''}" data-step="${name}" aria-pressed="${state.selected===name}"><span class="number">0${i+1}</span><b>${i===0&&state.view!=='phone'?'<span class="mark">2</span>':''}${name}</b>${pill(statusFor(name),name==='Implement'?'live':state.queued&&i>1?'warn':'')}<br><small>${['Research notes · v'+state.version,'Catalog code · isolated workspace','Evidence must match candidate','Preview target · preauthorized'][i]}</small></button>${concept==='b'&&state.selected===name?`<div class="step-details">${name==='Implement'?'Inputs: research v'+state.consumed+'<br>Latest: v'+state.version+' · '+(state.queued?'1 replacement queued':'up to date'):name==='Research'?'Published checkpoint<br>notes.md · ready':name==='Review'?'Waits for code + test report<br>Previous attempts preserved':'Merge design candidate<br>Then deploy to demo-preview'}</div>`:''}`).join('')}
function terminal(){return `<section class="terminal-area" aria-label="Terminal fixture"><div class="terminal-head"><div class="terminal-tabs"><b>${['connected','changed'].includes(state.view)?'<span class="mark">1</span>':''}${state.selected.toLowerCase()}-catalog</b><span>● ${state.phase==='stopped'?'Stopped':'Connected'}</span></div><div class="row">${button('split',state.split?'Single':'Split','small ghost')}${button('inspector',state.inspector?'Hide details':'Show details','small ghost')}</div></div><div class="terminal-panes ${state.split?'split':''}"><div class="pane"><div class="pane-title">${state.selected.toUpperCase()} / ATTEMPT ${state.reruns?2:1} / ${state.attached?'EXISTING SESSION ATTACHED':'CODER'}</div><div class="terminal-lines" tabindex="0" aria-label="Sample terminal output"><span class="dim">~/catalog-demo · isolated worktree</span>\n\n<span class="green">› ${esc(state.definition)}</span>\n\n${state.selected==='Research'?'Read 8 fixture files.\nFound the empty-query path.\n\n✓ Published notes.md v'+state.version+'\n✓ Ready checkpoint shared with Implement.':state.selected==='Review'?'Waiting for candidate and test report.\n\n'+(state.queued?'! Review for demo-a1b2 is outdated.\n  A new input changed the candidate.':'Input contract: exact commit + passing checks.'):state.selected==='Deploy'?(state.allowRelease?'Target: '+state.target+'\nPermitted: merge reviewed candidate, deploy.\n\nWaiting for fresh review evidence.\nNo eligible candidate yet.':'Deployment is not included in this run.\nA new definition review is required to add it.'):state.phase==='stopped'?'Attempt interrupted.\nQueued work cancelled.\nOutputs and history preserved.':`✓ Read research/notes.md · v${state.consumed}\n✓ Reproduced empty-query behavior\n✓ Added accessible filter controls\n\n<span class="dim">Running focused checks…</span>\n  search empty state     PASS\n  keyboard selection    PASS\n\n${state.queued?'<span class="yellow">↳ Input v'+state.version+' queued for next boundary.\n  Current attempt is stale; replacement pending.</span>':'<span class="green">▍</span> Preparing candidate summary'}`}</div></div>${state.split?`<div class="pane"><div class="pane-title">RESEARCH / PUBLISHED OUTPUT</div><div class="terminal-lines"><span class="green">✓ Checkpoint ready · v${state.version}</span>\n\nnotes.md\n  - Preserve typed queries\n  - Explain empty results\n  - Keep focus in search\n${state.version>1?'  + Add keyboard-clear behavior\n':''}\n<span class="dim">Delivery to Implement</span>\nSource: research-demo\nSequence: ${state.version===1?'18':'19'}\nDelivered: ${state.delivery==='queued'?'waiting for boundary':'yes'}\nConsumed: v${state.consumed}\n\n<span class="dim">Selected snapshots only.\nProducer files stay isolated.</span></div></div>`:''}</div><div class="terminal-mode"><span>${state.view==='phone'?'<span class="mark">2</span>':''}Touch mode · ${state.mode}</span><div class="row">${['Scroll','Select','Type'].map(m=>`<button type="button" class="small mode-btn" data-mode="${m}" aria-pressed="${state.mode===m}">${m}</button>`).join('')}</div></div><div class="composer"><textarea id="draft" aria-label="Message draft" placeholder="Write a message… drafts stay here">${esc(state.draft)}</textarea>${button('send','Send','small')}</div><div class="composer-note">${state.mode==='Type'?'Type into the composer. Send queues a fixture message.':state.mode==='Select'?'Select sample output to copy. Composer remains available.':'Scroll sample output. Composer remains available; nothing is sent on tap.'}</div></section>`}
function detail(){let content='';
 if(state.tab==='Inputs')content=`<h2><span class="mark">3</span>Inputs to ${state.selected}</h2><p class="kicker">Versioned references · live subscription</p><div class="input-card"><h3>${pill('Ready','live')} Research notes</h3><p>research-demo → implement-demo</p><code>notes.md · snapshot v${state.consumed}</code><div class="meta"><span>Latest<br><strong>v${state.version}</strong></span><span>Consumed<br><strong>v${state.consumed}</strong></span></div></div><p class="muted">${state.queued?'New input queued. One replacement will use the latest version after this attempt finishes.':'The ready checkpoint starts Implement. Final results unblock Review.'}</p>${button('input-update','Simulate input change','small')}<div class="meta"><span>Concurrency<br><strong>2 steps</strong></span><span>Rerun budget<br><strong>${state.reruns} / 3 used</strong></span></div>`;
 if(state.tab==='Updates')content=`<h2><span class="mark">3</span>Live handoffs</h2><p class="kicker">Source, delivery and consumption stay separate</p><div class="input-card"><h3>${pill(state.queued?'Queued at boundary':'Consumed',state.queued?'warn':'live')}</h3><p>Research · sequence ${state.version+17} · v${state.version}</p><p>“Keyboard clear must preserve focus.”</p><div class="meta"><span>Delivered<br><strong>${state.delivery==='queued'?'Pending':state.delivery==='delivered'?'Yes · waiting':'Yes'}</strong></span><span>Consumed<br><strong>${state.consumed===state.version?'Yes':'No · v'+state.consumed+' in use'}</strong></span></div></div><p class="muted">${state.queued?'Review for demo-a1b2 is invalidated. Release waits for new code and matching evidence.':'No updates pending. Prior messages remain in history.'}</p>${state.queued?button('deliver','Deliver at boundary','small')+button('finish',state.paused?'Finish attempt (paused)':'Finish attempt & rerun','small'):button('input-update','Simulate input change','small')}<p class="check-note">${state.paused?'Paused: no new attempts dispatch.':'Changes coalesce into one replacement.'}</p><div class="input-card"><h3>${state.retryFailed?'Delivery failed':'Delivery simulator'}</h3><p>${state.retryFailed?'Transport unavailable. Message retained; retry uses the same delivery ID.':'Try a recoverable transport failure.'}</p>${button(state.retryFailed?'retry':'fail',state.retryFailed?'Retry delivery':'Simulate failure','small')}</div>${state.notes.map(n=>`<p class="check-note">${esc(n)}</p>`).join('')}`;
 if(state.tab==='Files')content=`<h2>Shared snapshots</h2><p class="kicker">Explicit selections; no shared mutable folders</p><div class="input-card"><h3>research/notes.md</h3><p>Version ${state.version} · ${state.version===1?'3':'4'} findings</p>${button('file','View snapshot','small')}</div><div class="input-card"><h3>Candidate · demo-a1b2</h3><p>Implementation attempt 1</p>${pill(state.queued?'Stale · kept in history':'Current candidate',state.queued?'warn':'')}</div>`;
 if(state.tab==='Result')content=`<h2>Review summary</h2><p class="kicker">Previous attempt · candidate demo-a1b2</p><div class="input-card"><h3>${pill(state.queued?'Outdated review':'Previous result · retained',state.queued?'warn':'live')}</h3><p>Empty queries now show a useful next step. Keyboard focus stays in search.</p><p>Checks: 12 passed · 0 failed</p><code>Evidence → demo-a1b2</code></div><p class="muted">${state.queued?'This evidence cannot release newer code. A replacement review will run after implementation.':'Fixture summary from a previous candidate; this run still waits for its final inputs.'}</p>${button('history','View attempt history','small')}`;
 if(state.tab==='Task')content=`<h2>${esc(state.definition)}</h2><p class="kicker">Run 024 · definition v${state.revision}</p><p>Research → Implement → Review → Deploy</p><div class="input-card"><h3>Allowed actions</h3><p>${state.allowRelease?`Read, edit, test, review, merge the reviewed candidate and deploy to <b>${state.target}</b>.`:'Read, edit, test and review. No release action included.'}</p><p>Release requires matching commit evidence.</p></div><p class="muted">2 concurrent steps · 3 reruns per step. Start freezes this scope.</p>${button('proposal','Propose new run','small')}${button('attach','Connect existing terminal','small')}`;
 return `<aside class="inspector ${state.inspector?'':'hidden'}" aria-label="Step details"><nav class="inspector-tabs" aria-label="Inspector sections">${['Task','Inputs','Updates','Files','Result'].map(t=>`<button type="button" data-tab="${t}" class="${state.tab===t?'active':''}" aria-pressed="${state.tab===t}">${t}</button>`).join('')}</nav><div class="inspector-body">${content}</div></aside>`}
function overviewCards(){return `<div class="overview-cards"><article class="task-card">${pill('Agent running','live')}<h2>Improve catalog search</h2><p>Research is ready. Implement is running with its published notes.</p><div class="progress"><span></span></div><div class="card-meta">1 of 4 steps finished · catalog-demo</div>${button('open-work','Open workspace →','primary')}</article><article class="task-card">${pill(state.attention?'Needs you':'Answer queued',state.attention?'warn':'live')}<h2>Review release notes</h2><p>${state.attention?'The editor needs a decision on the audience before it can continue.':'Answer queued. The editor will consume it at the next safe boundary.'}</p><div class="card-meta">Waiting for input · docs-demo</div>${button('attention','Review question →')}</article><article class="task-card">${pill('Finished')}<h2>Check image links</h2><p>All 24 fixture assets resolve. The result and checks are ready.</p><div class="card-meta">Finished 12 minutes ago · catalog-demo</div>${button('finished-result','Read result →')}</article></div>`}
function annotations(){const id=concept.toUpperCase();const notes=state.view==='overview'?[
 ['A place for attention',concept==='a'?'Work stays in a fixed order. Attention has its own small queue.':'Cards answer what is running, what needs you and what finished.'],
 ['Connected, not crowded',concept==='a'?'A compact strip keeps the full chain visible above the terminal.':'Open a task to reach its terminal and expandable step details.'],
 ['Inspect without losing work','Inputs and results open beside the terminal; updates preserve drafts.']
 ]:state.view==='changed'?[
 ['Keep the active attempt','New inputs mark this attempt stale. It finishes before a replacement starts.'],
 ['Coalesce upstream changes','Only the newest input set is consumed by the next attempt; earlier outputs remain.'],
 ['Invalidate stale evidence','The previous review cannot release changed code. Delivery and consumption are distinct.']
 ]:state.view==='phone'?[
 ['Review first','Attention and result summaries sit above quick terminal access.'],
 ['Touch has explicit modes','Scroll, Select and Type remain visible. Tapping output does not send keystrokes.'],
 ['Same run, smaller surface','Phone and desktop show the same inputs, evidence and scheduling controls.']
 ]:[
 ['Terminals stay central','Compare implementation and its research output without changing sessions.'],
 ['Attach without restarting','An existing terminal keeps its process and history; unsupported delivery needs setup.'],
 ['Visible handoffs','Inspect versioned inputs, their source and acknowledgment before work continues.']
 ];return `<footer><div class="annotation">${notes.map((n,i)=>`<p><strong><span class="mark">${i+1}</span>${n[0]}</strong>${n[1]}</p>`).join('')}</div><div class="frame-label">${id}${['overview','connected','changed','phone'].indexOf(state.view)+1} · ${state.view.toUpperCase()} · DESIGN FIXTURE / OCT 2026</div></footer>`}
function render(){syncDraft();const focused=document.activeElement?.id;const selection=focused==='draft'?[document.activeElement.selectionStart,document.activeElement.selectionEnd]:null;const scrollY=window.scrollY;const outputScroll=[...document.querySelectorAll('.terminal-lines')].map(el=>el.scrollTop);document.body.className=`${concept} ${state.theme==='dark'?'dark':''} ${state.view==='phone'?'phone-frame':''} ${concept==='b'&&state.view==='overview'?'task-landing':''}`;
 app.innerHTML=`<div class="review-bar"><div class="row"><a href="index.html">← Concepts</a><b>${concept==='a'?'A / Quiet workbench':'B / Task overview'}</b><span class="fixture-note muted">Interactive fixture</span></div><div class="row"><select class="frame-select" id="frame" aria-label="Review frame">${['overview','connected','changed','phone'].map((f,i)=>`<option value="${f}" ${state.view===f?'selected':''}>${concept.toUpperCase()}${i+1} · ${f}</option>`).join('')}</select>${button('theme',state.theme==='light'?'Dark':'Light','small ghost')}</div></div><div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon">a_</span>agent console</div>${button('project','Catalog demo ⌄','project')}<div class="side-work"><input class="search" id="search" aria-label="Search work" placeholder="Search work…" value="${esc(state.search)}"><p class="side-label" style="margin-top:25px">${esc(state.group.toUpperCase())} <span class="mark">1</span></p><div class="work-list"><button type="button" class="work-item active" data-action="open-work"><strong>${esc(state.definition)}</strong><small>● Agent running · 1/4 steps</small></button><button type="button" class="work-item" data-action="attention"><strong>Review release notes</strong><small>${state.attention?'◷ Waiting for input · needs you':'↳ Answer queued · next boundary'}</small></button><button type="button" class="work-item" data-action="finished-result"><strong>Check image links</strong><small>✓ Finished · 12m ago</small></button></div><label class="check-note" for="group">Move selected work</label><select id="group" class="search" aria-label="Move selected work">${['Active work','Later','Reference'].map(g=>`<option ${state.group===g?'selected':''}>${g}</option>`).join('')}</select></div><div class="attention-mini"><b>${state.attention?'1 needs your attention':'No decisions pending'}</b><br>${button('attention','Review release notes →')}</div><div class="sidebar-bottom">${button('settings','⚙ Settings','ghost')}<p class="muted" style="margin:12px 0 0">● System ready · 2 / 6 slots</p></div></aside><main id="main" class="main"><div class="topline row between"><span>Catalog demo / ${concept==='b'&&state.view==='overview'?'Your work':'Search experience'}</span><span>${state.paused?'Scheduling paused':'Live'} · updated just now</span></div><header class="toolbar"><div><h1>${concept==='b'&&state.view==='overview'?'Your work, in view.':esc(state.definition)}</h1><p>${concept==='b'&&state.view==='overview'?'One decision needs you. Everything else is moving.':'Research → Implement → Review → Deploy · Run 024'}</p></div><div class="toolbar-actions">${button('proposal','＋ Propose work',concept==='b'&&state.view==='overview'?'primary':'')}${button('pause',state.paused?'Resume':'Pause')}${button('stop','Stop','danger')}</div></header>${concept==='b'&&state.view==='overview'?overviewCards():''}${state.view==='phone'?`<section class="mobile-review"><div class="row between"><b><span class="mark">1</span>${state.attention?'1 decision needs you':'Answer queued'}</b>${pill(state.attention?'Needs input':'Answer queued',state.attention?'warn':'live')}</div><p>${state.attention?'Release notes are waiting for an audience choice.':'Your answer is queued at the next turn boundary.'}</p>${button('attention','Review question','small')} ${button('show-result','Read result','small')} ${button('terminal','Open terminal ↓','small')}</section>`:''}<div class="notice ${state.queued?'changed':''}"><span>${state.queued?`<b>Input changed to v${state.version}.</b> ${state.paused?'Replacement waiting for Resume.':'One replacement queued.'} Review invalidated; release blocked.`:state.phase==='stopped'?'<b>Stopped.</b> Active attempts interrupted. Outputs kept.':state.paused?'<b>Paused.</b> Active attempts continue. No new work will dispatch.':'<b>Research is ready.</b> Implement consumed notes v'+state.consumed+'. Review waits for its candidate.'}</span>${button(state.queued?'show-updates':'attach',state.queued?'Inspect update':'Connect terminal','small')}</div><div class="connected-layout"><nav class="chain" aria-label="Connected steps">${steps()}</nav><div class="workspace ${state.inspector?'':'collapsed'}">${terminal()}${detail()}</div></div>${annotations()}</main></div>`;
 if(focused==='draft'){const d=document.getElementById('draft');d.focus({preventScroll:true});d.setSelectionRange(...selection)}document.querySelectorAll('.terminal-lines').forEach((el,i)=>el.scrollTop=outputScroll[i]||0);window.scrollTo(0,scrollY);filterWork();}
function filterWork(){document.querySelectorAll('.work-item').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(state.search.toLowerCase()))}
function openDialog(html){dialog.innerHTML=html;dialog.showModal()}
function proposal(edit=false){syncDraft();const p=state.proposal||{definition:state.definition,target:state.target,allowRelease:state.allowRelease};state.proposal=p;openDialog(`<p class="eyebrow">AGENT PROPOSAL · DEFINITION V${state.revision+1}</p><h2>${edit?'Edit connected work':'A proposed path to completion'}</h2><p class="muted">Review the steps, selected inputs and permitted actions before starting.</p><label>Work title<input id="work-title" value="${esc(p.definition)}" ${edit?'':'readonly'}></label><div class="definition-row"><strong>Step / agent</strong><strong>Required input → output</strong><strong>Permitted actions</strong></div>${names.map((n,i)=>`<div class="definition-row"><strong>${i+1}. ${n}<br><span class="muted">${['Researcher','Coder','Reviewer','Releaser'][i]} · demo harness</span></strong><span>${['Task → notes.md ready','Notes ready → candidate + checks','Candidate + checks → commit evidence','Matching evidence → receipt'][i]}</span><span>${['Read fixture repo','Edit + test isolated code','Read + verify candidate',p.allowRelease?'Merge candidate + deploy':'Publish review only'][i]}</span></div>`).join('')}<label>Repository<input value="example/catalog-demo" readonly></label><label>Release target<select id="release-target" ${edit?'':'disabled'}><option ${p.target==='demo-preview'?'selected':''}>demo-preview</option><option ${p.target==='demo-staging'?'selected':''}>demo-staging</option></select></label><p class="check-note">2 concurrent steps · maximum 3 automatic reruns per step · live updates at safe turn boundaries. Start freezes this definition; broader scope needs another review.</p>${edit?`<label><input id="allow-release" type="checkbox" ${p.allowRelease?'checked':''}>Include merge and deployment to the selected demo target</label>`:''}<div class="dialog-actions">${button('close','Cancel')}${button(edit?'save-definition':'edit-definition',edit?'Save definition':'Edit proposal')}${!edit?button('start','Start listed steps','primary'):''}</div>`)}
function update(){if(state.phase==='stopped'){toast('Run is stopped. Propose new work to continue.');return}state.version++;state.queued=true;state.delivery='queued';state.phase='changed';state.released=false;state.view='changed';state.tab='Updates';render();toast(`Input v${state.version} queued. Earlier changes coalesce into one replacement.`)}
function finish(){if(state.phase==='stopped'){toast('Stopped runs cannot dispatch attempts.');return}if(!state.queued){toast('No replacement pending.');return}if(state.paused){state.pending=true;toast('Attempt finished. Replacement waits for Resume.');return}if(state.reruns>=3){state.paused=true;render();toast('Rerun limit reached. Scheduling paused for operator review.');return}state.consumed=state.version;state.delivery='consumed';state.queued=false;state.pending=false;state.reruns++;state.phase='running';state.notes.push(`Attempt ${state.reruns+1} consumed v${state.version}; previous attempt retained.`);render();toast(`Replacement attempt ${state.reruns+1} started with latest input v${state.version}.`)}
const actions={
 'theme':()=>{state.theme=state.theme==='light'?'dark':'light';render()},
 'split':()=>{state.split=!state.split;render()},
 'inspector':()=>{state.inspector=!state.inspector;render()},
 'open-work':()=>{state.view='connected';state.split=true;render()},
 'proposal':()=>{state.proposal=null;proposal()}, 'edit-definition':()=>proposal(true),
 'save-definition':()=>{state.proposal={definition:document.getElementById('work-title').value.trim()||'Improve catalog search',target:document.getElementById('release-target').value,allowRelease:document.getElementById('allow-release').checked};dialog.close();proposal()},
 'start':()=>{Object.assign(state,state.proposal);state.proposal=null;dialog.close();state.revision++;state.phase='running';state.delivery='consumed';state.paused=false;state.view='connected';state.selected='Implement';state.queued=false;state.version=state.consumed=1;state.reruns=0;state.pending=false;state.notes=[];render();toast('Definition frozen. Fixture run started; listed actions authorized for this simulation.')},
 'close':()=>dialog.close(),
 'pause':()=>{if(state.phase==='stopped'){toast('Run is stopped. Propose new work to continue.');return}state.paused=!state.paused;if(!state.paused&&state.pending){finish();return}render();toast(state.paused?'Paused new dispatches. Active attempts continue.':'Scheduling resumed within the frozen definition.')},
 'stop':()=>openDialog(`<h2>Stop this run?</h2><p>Interrupt active attempts and cancel queued steps. Published outputs and attempt history are preserved.</p><div class="dialog-actions">${button('close','Keep running')}${button('confirm-stop','Stop run','danger')}</div>`),
 'confirm-stop':()=>{dialog.close();state.phase='stopped';state.queued=false;state.pending=false;state.paused=false;render();toast('Fixture run stopped. History preserved.')},
 'show-updates':()=>{state.tab='Updates';state.inspector=true;render()},
 'terminal':()=>document.querySelector('.terminal-area').scrollIntoView({behavior:'smooth',block:'start'}),
 'show-result':()=>{state.tab='Result';state.inspector=true;render();document.querySelector('.inspector').scrollIntoView({behavior:'smooth',block:'start'})},
 'input-update':update, 'finish':finish,
 'fail':()=>{state.retryFailed=true;render()},
 'retry':()=>{state.retryFailed=false;state.delivery='delivered';render();toast('Retry succeeded. Original delivery ID retained; no duplicate input.')},
 'deliver':()=>{state.delivery='delivered';render();toast('Delivered at a safe boundary. Consumption waits for the replacement attempt.')},
 'attach':()=>openDialog(`<p class="eyebrow">CONNECT WITHOUT RESTARTING</p><h2>Use an existing terminal</h2><p class="muted">Process, scrollback and working directory stay intact.</p><label>Session<select id="attach-session"><option value="supported">catalog-notes · sess-demo-42 · ready</option><option value="unsupported">legacy-shell · sess-demo-43 · setup required</option></select></label><p id="attach-help">Supports safe input delivery and structured outputs.</p><div class="dialog-actions">${button('close','Cancel')}${button('confirm-attach','Connect terminal','primary')}</div>`),
 'confirm-attach':()=>{if(document.getElementById('attach-session').value==='unsupported'){toast('Setup required: this harness cannot accept safe automatic input.');return}state.attached=true;dialog.close();render();toast('sess-demo-42 connected. Existing process and history preserved.')},
 'attention':()=>openDialog(`<p class="eyebrow">REVIEW RELEASE NOTES · WAITING FOR INPUT</p><h2>Who are these notes for?</h2><p>The editor needs an audience before publishing its result.</p><label>Audience<select id="audience"><option>Operators</option><option>Developers</option></select></label><div class="dialog-actions">${button('close','Later')}${button('answer','Send answer','primary')}</div>`),
 'answer':()=>{const a=document.getElementById('audience').value;state.attention=false;dialog.close();render();toast(`Answer queued for the editor: ${a}. Delivery at the next safe boundary.`)},
 'finished-result':()=>openDialog(`<p class="eyebrow">CHECK IMAGE LINKS · FINISHED</p><h2>All 24 fixture assets resolve.</h2><p>24 passed · 0 failed. Result published 12 minutes ago.</p><div class="input-card"><code>link-check.json · v1 · final result</code></div><div class="dialog-actions">${button('close','Done','primary')}</div>`),
 'history':()=>openDialog(`<h2>Attempt history</h2><div class="input-card"><h3>Attempt 1 · demo-a1b2</h3><p>Input notes v1 · ${state.version>1?'stale, preserved':'current'} · 12 checks passed</p></div>${state.reruns?`<div class="input-card"><h3>Attempt ${state.reruns+1} · running</h3><p>Input notes v${state.consumed} · awaiting fresh review</p></div>`:''}<p class="muted">Evidence stays tied to its candidate commit.</p><div class="dialog-actions">${button('close','Done')}</div>`),
 'file':()=>openDialog(`<h2>research/notes.md · v${state.version}</h2><p>Preserve typed queries.<br>Explain empty results.<br>Keep focus in search.${state.version>1?'<br>Add keyboard-clear behavior.':''}</p><p class="muted">Read-only selected snapshot from research-demo.</p><div class="dialog-actions">${button('close','Done')}</div>`),
 'send':()=>{syncDraft();if(!state.draft.trim()){toast('Write a message first.');return}state.notes.push('Operator message queued: '+state.draft);state.draft='';document.getElementById('draft').value='';toast('Message queued. It will be delivered at a safe turn boundary.')},
 'settings':()=>openDialog(`<h2>Workspace settings</h2><p class="muted">Configuration lives away from everyday work.</p><div class="input-card"><h3>Profiles, models and skills</h3><p>Researcher, Coder, Reviewer, Releaser · demo harness</p></div><div class="input-card"><h3>Diagnostics</h3><p>System ready · 2 of 6 sessions · 2 concurrent workflow steps</p></div><div class="dialog-actions">${button('close','Done')}</div>`),
 'project':()=>openDialog(`<h2>Project</h2><p>Catalog demo · example/catalog-demo</p><p class="muted">This review uses one fictional project across both concepts.</p><div class="dialog-actions">${button('close','Done')}</div>`)
};
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.action)actions[el.dataset.action]?.();else if(el.dataset.tab){state.tab=el.dataset.tab;render()}else if(el.dataset.step){state.selected=el.dataset.step;render()}else if(el.dataset.mode){state.mode=el.dataset.mode;render();if(state.mode==='Type')document.getElementById('draft').focus()}});
document.addEventListener('input',e=>{if(e.target.id==='draft')state.draft=e.target.value;if(e.target.id==='search'){state.search=e.target.value;filterWork()}});
document.addEventListener('change',e=>{if(e.target.id==='frame')location.href=`${concept}.html?frame=${e.target.value}&theme=${state.theme}`;if(e.target.id==='group'){state.group=e.target.value;render();toast(`Moved selected work to ${state.group}. Order remains stable.`)}if(e.target.id==='attach-session'){const unsupported=e.target.value==='unsupported';document.getElementById('attach-help').textContent=unsupported?'Setup required: safe automatic input is not supported. Connection is disabled.':'Supports safe input delivery and structured outputs.';dialog.querySelector('[data-action=confirm-attach]').disabled=unsupported}});
render();
